    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    for (int vertex : minLabelBucket) {
        labels.set(vertex, 0);
        bucketsByLabel.get(0).add(vertex);
    }

    // Clear the bucket with label 'minLabel'
    minLabelBucket.clear();

    // Update the labeling accordingly
    for (int label = 0; label < bucketsByLabel.size(); label++) {
        if (label != minLabel && !bucketsByLabel.get(label).isEmpty()) {
            Set<Integer> currentLabelBucket = bucketsByLabel.get(label);
            for (int vertex : currentLabelBucket) {
                labels.set(vertex, label);
            }
        }
    }
}

