    if (className == null) {
        throw new ClassNotFoundException("Class name cannot be null.");
    }

    // Load from classpath
    /*
    ClassLoader classLoader = ClassLoader.getSystemClassLoader();
    Class clazz = classLoader.loadClass(className);
    */

    // Load from file
    File file = new File(className + ".class");
    if (!file.exists()) {
        throw new ClassNotFoundException("Class file not found: " + className);
    }

    FileInputStream fis = new FileInputStream(file);
    ClassReader cr = new ClassReader(fis);
    fis.close();

    // Get class name from file
    String className = cr.getClassName();
    if (className == null) {
        throw new ClassNotFoundException("Class name cannot be null.");
    }

    // Remove package prefix if it exists
    int lastDot = className.lastIndexOf('.');
    if (lastDot != -1) {
        className = className.substring(lastDot + 1);
    }

    try {
        Class<?> clazz = Class.forName(className);
        return clazz;
    } catch (ClassNotFoundException e) {
        throw new ClassNotFoundException("Class not found: " + className, e);
    }
}

