private boolean unlink(ListNodeImpl<E> node) {
    boolean removed = false;
    /*
     * 1. Find the previous node of {@code node}. 
     * 2. Remove {@code node} from the list by updating the pointers of the previous and next nodes.
     * 3. Set the next and previous nodes of {@code node} to null.
     */
    ListNodeImpl<E> tmp1 = head;
    ListNodeImpl<E> tmp2 = null;
    while (tmp1 != null) {
        if (tmp1 == node) {
            if (tmp2 == null) { // Node is the head.
                head = node.next;
            } else {
                tmp2.next = node.next;
            }
            if (node.next == null) { // Node is the tail.
                tail = tmp2;
            } else {
                node.next.prev = tmp2;
            }
            node.next = null;
            node.prev = null;
            size--;
            removed = true;
            break;
        }
        tmp2 = tmp1;
        tmp1 = tmp1.next;
    }
    return removed;
}

