private String parseToken(final char[] terminators) {
    // Initialize a StringBuilder to store the token
    StringBuilder token = new StringBuilder();

    // Loop until a terminator is encountered
    while (position < input.length()) {
        char c = input.charAt(position);
        if (Arrays.binarySearch(terminators, c) >= 0) {
            // If a terminator is encountered, break the loop
            break;
        } else {
            // If the character is not a terminator, add it to the token
            token.append(c);
            position++;
        }
    }

    // Return the parsed token
    return token.toString();
}

