int globalSeparatorList(Graph graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();

    for (E edge : graph.edges()) {
        List<Pair<Integer, Integer>> minSeparator = computeMinSeparator(graph, edge);
        separatorList.add(new Pair(minSeparator, edge));
    }

    return separatorList;
}

/**
 * Computes the min separator for a given edge in a graph
 * @param graph the input graph
 * @param edge the edge to compute the separator for
 * @return the min separator of the edge in the graph
 */
private List<Pair<Integer, Integer>> computeMinSeparator(Graph graph, E edge) {
    Set<V> source = graph.incomingEdges(edge.source());
    Set<V> target = graph.incomingEdges(edge.target());
    Set<V> intersection = new HashSet<>(source);
    intersection.retainAll(target);
    List<Pair<Integer, Integer>> minSeparator = new ArrayList<>();

    for (V vertex : intersection) {
        Pair<Integer, Integer> separatorPair = new Pair(vertex.getId(), edge.getId());
        minSeparator.add(separatorPair);
    }

    return minSeparator;
}

