public List<Integer> computeLowerBounds(List<K> keys) {
    if (keys.size() == 0) {
        return Collections.emptyList();
    }
    Collections.sort(keys);
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        Integer lowerBound = key;
        for (int j = i + 1; j < keys.size(); j++) {
            K nextKey = keys.get(j);
            if (key.compareTo(nextKey) > 0) {
                break;
            }
            lowerBound = Math.min(lowerBound, nextKey);
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private void pop(String descriptor) {
    if (descriptor == null || descriptor.trim().isEmpty()) {
        return;
    }
    if (descriptor.startsWith("(")) {
        descriptor = descriptor.substring(1, descriptor.length() - 1);
    }
    while (descriptor.contains("<")) {
        descriptor = descriptor.substring(1, descriptor.length() - 1);
    }
    if (descriptor.equals("Ljava/lang/invoke/MethodHandles$Lookup;")) {
        pop(descriptor);
    } else {
        stack.pop();
    }
}

